// A small, real decoder-only transformer. No ML library, server, or hidden API.
// Matrices are row-major. Reverse-mode autodiff records one closure per operation.
export class RNG {
  constructor(seed=42){this.state=seed>>>0;}
  next(){let t=this.state+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;}
  normal(){return Math.sqrt(-2*Math.log(Math.max(1e-12,this.next())))*Math.cos(2*Math.PI*this.next());}
}
export class Tensor {
  constructor(data,rows,cols,parents=[],back=null){this.data=Float64Array.from(data);this.rows=rows;this.cols=cols;this.grad=new Float64Array(data.length);this.parents=parents;this.back=back;}
  backward(){const order=[],seen=new Set();const visit=t=>{if(seen.has(t))return;seen.add(t);t.parents.forEach(visit);order.push(t);};visit(this);this.grad[0]=1;for(let i=order.length-1;i>=0;i--)order[i].back?.();}
}
export function add(a,b){const broad=b.rows===1;const out=new Tensor(a.data.map((x,i)=>x+b.data[broad?i%b.cols:i]),a.rows,a.cols,[a,b]);out.back=()=>{for(let i=0;i<out.grad.length;i++){a.grad[i]+=out.grad[i];b.grad[broad?i%b.cols:i]+=out.grad[i];}};return out;}
export function matmul(a,b){const M=a.rows,K=a.cols,N=b.cols,d=new Float64Array(M*N);for(let i=0;i<M;i++)for(let k=0;k<K;k++){const v=a.data[i*K+k];for(let j=0;j<N;j++)d[i*N+j]+=v*b.data[k*N+j];}const out=new Tensor(d,M,N,[a,b]);out.back=()=>{for(let i=0;i<M;i++)for(let k=0;k<K;k++){let g=0;for(let j=0;j<N;j++){const v=out.grad[i*N+j];g+=v*b.data[k*N+j];b.grad[k*N+j]+=a.data[i*K+k]*v;}a.grad[i*K+k]+=g;}};return out;}
export function gather(table,ids){const D=table.cols,d=new Float64Array(ids.length*D);ids.forEach((id,i)=>d.set(table.data.subarray(id*D,(id+1)*D),i*D));const out=new Tensor(d,ids.length,D,[table]);out.back=()=>ids.forEach((id,i)=>{for(let j=0;j<D;j++)table.grad[id*D+j]+=out.grad[i*D+j];});return out;}
export function layernorm(x,gamma,beta){const D=x.cols,y=new Float64Array(x.data.length),z=new Float64Array(y.length),inv=new Float64Array(x.rows);for(let i=0;i<x.rows;i++){let mean=0,v=0;for(let j=0;j<D;j++)mean+=x.data[i*D+j]/D;for(let j=0;j<D;j++)v+=(x.data[i*D+j]-mean)**2/D;inv[i]=1/Math.sqrt(v+1e-5);for(let j=0;j<D;j++){z[i*D+j]=(x.data[i*D+j]-mean)*inv[i];y[i*D+j]=z[i*D+j]*gamma.data[j]+beta.data[j];}}const out=new Tensor(y,x.rows,D,[x,gamma,beta]);out.back=()=>{for(let i=0;i<x.rows;i++){let meanG=0,meanGZ=0;for(let j=0;j<D;j++){const n=i*D+j,g=out.grad[n]*gamma.data[j];meanG+=g/D;meanGZ+=g*z[n]/D;gamma.grad[j]+=out.grad[n]*z[n];beta.grad[j]+=out.grad[n];}for(let j=0;j<D;j++){const n=i*D+j;x.grad[n]+=inv[i]*(out.grad[n]*gamma.data[j]-meanG-z[n]*meanGZ);}}};return out;}
export function gelu(x){const c=Math.sqrt(2/Math.PI),y=x.data.map(v=>.5*v*(1+Math.tanh(c*(v+.044715*v*v*v))));const out=new Tensor(y,x.rows,x.cols,[x]);out.back=()=>{for(let i=0;i<y.length;i++){const v=x.data[i],t=Math.tanh(c*(v+.044715*v*v*v));x.grad[i]+=out.grad[i]*(.5*(1+t)+.5*v*(1-t*t)*c*(1+.134145*v*v));}};return out;}
export function attention(q,k,v,heads){const T=q.rows,D=q.cols,H=D/heads,scale=1/Math.sqrt(H),a=new Float64Array(heads*T*T),y=new Float64Array(T*D);for(let h=0;h<heads;h++)for(let i=0;i<T;i++){let max=-Infinity;for(let j=0;j<=i;j++){let s=0;for(let d=0;d<H;d++)s+=q.data[i*D+h*H+d]*k.data[j*D+h*H+d];a[h*T*T+i*T+j]=s*scale;max=Math.max(max,s*scale);}let sum=0;for(let j=0;j<=i;j++)sum+=(a[h*T*T+i*T+j]=Math.exp(a[h*T*T+i*T+j]-max));for(let j=0;j<=i;j++){const w=a[h*T*T+i*T+j]/=sum;for(let d=0;d<H;d++)y[i*D+h*H+d]+=w*v.data[j*D+h*H+d];}}const out=new Tensor(y,T,D,[q,k,v]);out.weights=a;out.back=()=>{for(let h=0;h<heads;h++)for(let i=0;i<T;i++){const da=new Float64Array(i+1);let weighted=0;for(let j=0;j<=i;j++){const w=a[h*T*T+i*T+j];for(let d=0;d<H;d++){const g=out.grad[i*D+h*H+d];da[j]+=g*v.data[j*D+h*H+d];v.grad[j*D+h*H+d]+=w*g;}weighted+=da[j]*w;}for(let j=0;j<=i;j++){const ds=a[h*T*T+i*T+j]*(da[j]-weighted)*scale;for(let d=0;d<H;d++){q.grad[i*D+h*H+d]+=ds*k.data[j*D+h*H+d];k.grad[j*D+h*H+d]+=ds*q.data[i*D+h*H+d];}}}};return out;}
export function crossEntropy(logits,targets){const T=logits.rows,V=logits.cols,p=new Float64Array(T*V);let loss=0;for(let i=0;i<T;i++){let max=-Infinity;for(let j=0;j<V;j++)max=Math.max(max,logits.data[i*V+j]);let sum=0;for(let j=0;j<V;j++)sum+=(p[i*V+j]=Math.exp(logits.data[i*V+j]-max));loss+=(Math.log(sum)+max-logits.data[i*V+targets[i]])/T;for(let j=0;j<V;j++)p[i*V+j]/=sum;}const out=new Tensor([loss],1,1,[logits]);out.back=()=>{for(let i=0;i<T;i++)for(let j=0;j<V;j++)logits.grad[i*V+j]+=out.grad[0]*(p[i*V+j]-(j===targets[i]?1:0))/T;};return out;}
export function probabilities(logits,temperature=1,topK=0){if(!Number.isFinite(temperature)||temperature<0||!Number.isInteger(topK)||topK<0)throw Error('Invalid sampling settings.');const ranked=Array.from(logits,(_,i)=>i).sort((a,b)=>logits[b]-logits[a]);if(temperature===0)return Array.from(logits,(_,i)=>i===ranked[0]?1:0);const keep=new Set(ranked.slice(0,topK||ranked.length)),max=logits[ranked[0]],p=Array.from(logits,(x,i)=>keep.has(i)?Math.exp((x-max)/temperature):0),s=p.reduce((a,b)=>a+b,0);return p.map(x=>x/s);}
export function sample(p,rng){let r=rng.next();for(let i=0;i<p.length;i++){r-=p[i];if(r<=0)return i;}return p.length-1;}

export class Transformer {
  constructor(text,config={}){
    this.config={dim:24,heads:2,context:24,seed:42,split:.85,...config};const {dim:D,heads,context:T,seed,split}=this.config;
    if(![16,24,32].includes(D)||![1,2,4].includes(heads)||D%heads||![8,16,24,32].includes(T)||!Number.isFinite(seed)||!Number.isFinite(split)||split<.65||split>.9)throw Error('Invalid model configuration.');
    if(typeof text!=='string'||Array.from(text).length<160||Array.from(text).length>20000)throw Error('Use between 160 and 20,000 characters.');
    this.text=text;this.vocab=[...new Set(Array.from(text))].sort();if(this.vocab.length>160||this.vocab.length<2)throw Error('Use 2–160 unique characters.');
    this.lookup=new Map(this.vocab.map((x,i)=>[x,i]));this.ids=Array.from(text,c=>this.lookup.get(c));this.cut=Math.floor(this.ids.length*split);if(this.ids.length-this.cut<T+1)throw Error('The held-out section needs more text, or a shorter context.');
    this.rng=new RNG(seed);this.step=0;this.params={};this.history=[];const V=this.vocab.length;
    const param=(name,r,c,mode='random')=>{const a=new Float64Array(r*c);for(let i=0;i<a.length;i++)a[i]=mode==='one'?1:mode==='zero'?0:this.rng.normal()*.08;const t=new Tensor(a,r,c);t.m=new Float64Array(a.length);t.v=new Float64Array(a.length);this.params[name]=t;return t;};
    param('token',V,D);param('position',T,D);for(const n of ['ln1','ln2','lnf']){param(n+'g',1,D,'one');param(n+'b',1,D,'zero');}
    for(const n of ['q','k','v','o']){param(n+'w',D,D);param(n+'b',1,D,'zero');}
    param('fw',D,4*D);param('fb',1,4*D,'zero');param('pw',4*D,D);param('pb',1,D,'zero');param('uw',D,V);param('ub',1,V,'zero');
    this.count=Object.values(this.params).reduce((n,t)=>n+t.data.length,0);
  }
  encode(text){const chars=Array.from(text),unknown=[...new Set(chars.filter(c=>!this.lookup.has(c)))];if(unknown.length)throw Error('Not in this vocabulary: '+unknown.map(c=>JSON.stringify(c)).join(', ')+'. Edit the prompt or rebuild with text containing these characters.');return chars.map(c=>this.lookup.get(c));}
  forward(ids,inspect=false){const p=this.params,linear=(x,n)=>add(matmul(x,p[n+'w']),p[n+'b']),norm=(x,n)=>layernorm(x,p[n+'g'],p[n+'b']);const tokens=gather(p.token,ids),position=gather(p.position,ids.map((_,i)=>i)),x=add(tokens,position),n1=norm(x,'ln1'),q=linear(n1,'q'),k=linear(n1,'k'),v=linear(n1,'v'),att=attention(q,k,v,this.config.heads),mixed=linear(att,'o'),res1=add(x,mixed),n2=norm(res1,'ln2'),ff=gelu(linear(n2,'f')),projected=linear(ff,'p'),res2=add(res1,projected),final=norm(res2,'lnf'),logits=linear(final,'u');if(inspect)return {logits,tokens,position,x,n1,q,k,v,att,mixed,res1,n2,ff,projected,res2,final};return logits;}
  window(rng,validation=false){const start=validation?this.cut:0,end=validation?this.ids.length:this.cut,T=this.config.context,at=start+Math.floor(rng.next()*(end-start-T));return [this.ids.slice(at,at+T),this.ids.slice(at+1,at+T+1)];}
  trainStep(lr=.003,batch=4){if(!Number.isFinite(lr)||lr<=0||lr>.03)throw Error('Learning rate must be > 0 and ≤ 0.03.');for(const p of Object.values(this.params))p.grad.fill(0);let loss=0;for(let b=0;b<batch;b++){const [x,y]=this.window(this.rng);const l=crossEntropy(this.forward(x),y);loss+=l.data[0]/batch;l.backward();}let norm=0;for(const p of Object.values(this.params))for(let i=0;i<p.grad.length;i++){p.grad[i]/=batch;norm+=p.grad[i]**2;}norm=Math.sqrt(norm);if(!Number.isFinite(loss)||!Number.isFinite(norm))throw Error('Training became unstable. Reset and try a smaller learning rate.');const clip=Math.min(1,1/(norm+1e-12));const witness={before:this.params.qw.data[0],gradient:this.params.qw.grad[0]};this.step++;const c1=1-.9**this.step,c2=1-.999**this.step;for(const p of Object.values(this.params))for(let i=0;i<p.data.length;i++){const g=p.grad[i]*clip;p.m[i]=.9*p.m[i]+.1*g;p.v[i]=.999*p.v[i]+.001*g*g;p.data[i]-=lr*(p.m[i]/c1)/(Math.sqrt(p.v[i]/c2)+1e-8);}witness.after=this.params.qw.data[0];return {loss,gradNorm:norm,clipped:norm>1,witness};}
  evaluate(){const rng=new RNG(1701);let train=0,validation=0;for(let i=0;i<12;i++){let [x,y]=this.window(rng);train+=crossEntropy(this.forward(x),y).data[0]/12;[x,y]=this.window(rng,true);validation+=crossEntropy(this.forward(x),y).data[0]/12;}const point={step:this.step,train,validation};this.history.push(point);return point;}
  inspect(prompt){let ids=this.encode(prompt);if(!ids.length)ids=[this.ids[0]];ids=ids.slice(-this.config.context);const r=this.forward(ids,true),last=ids.length-1,V=this.vocab.length;return {chars:ids.map(x=>this.vocab[x]),ids,logits:Array.from(r.logits.data.slice(last*V)),attention:Array.from(r.att.weights),heads:this.config.heads,dim:this.config.dim,trace:Object.fromEntries(['tokens','position','x','n1','q','k','v','att','mixed','res1','n2','ff','projected','res2','final','logits'].map(n=>[n,{rows:r[n].rows,cols:r[n].cols,last:Array.from(r[n].data.slice(last*r[n].cols,(last+1)*r[n].cols))}]))};}
  snapshot(){return {format:'attention-lab-v1',text:this.text,config:this.config,step:this.step,rng:this.rng.state>>>0,history:this.history,weights:Object.fromEntries(Object.entries(this.params).map(([n,p])=>[n,{data:Array.from(p.data),m:Array.from(p.m),v:Array.from(p.v)}]))};}
  static restore(s){if(!s||s.format!=='attention-lab-v1')throw Error('This is not an Attention Lab model.');const m=new Transformer(s.text,s.config);if(!Number.isSafeInteger(s.step)||s.step<0||s.step>1e8)throw Error('Invalid training step.');for(const [n,p] of Object.entries(m.params)){for(const field of ['data','m','v']){const arr=s.weights?.[n]?.[field];if(!Array.isArray(arr)||arr.length!==p[field].length||arr.some(x=>!Number.isFinite(x)||Math.abs(x)>1e8||(field==='v'&&x<0)))throw Error('Invalid weights: '+n);p[field].set(arr);}}m.step=s.step;m.rng.state=(s.rng??42)>>>0;m.history=Array.isArray(s.history)?s.history.filter(p=>Number.isFinite(p.step)&&Number.isFinite(p.train)&&Number.isFinite(p.validation)).slice(-500):[];return m;}
}
